import numpy as np

def parse_amount(val, paren_mode='enclosed'):
    if pd.isna(val):
        return np.nan
    s = str(val).strip()
    if not s:
        return np.nan

    # Check negative
    has_cr = 'CR' in s
    has_minus = '-' in s
    if paren_mode == 'enclosed':
        has_paren = s.startswith('(') and s.endswith(')')
    elif paren_mode == 'any':
        has_paren = '(' in s or ')' in s
    elif paren_mode == 'both':
        has_paren = '(' in s and ')' in s

    is_negative = has_cr or has_minus or has_paren

    # Rule 4: Remove tokens ('C1' and 'C2') and strip out letters and spaces, keeping only digits, ',' and '.'
    s_clean = s.replace('C1', '').replace('C2', '')
    cleaned = ''.join(c for c in s_clean if c.isdigit() or c in ',.')
    if not cleaned:
        return np.nan

    # Separator logic
    has_comma = ',' in cleaned
    has_dot = '.' in cleaned

    if has_comma and has_dot:
        last_comma = cleaned.rfind(',')
        last_dot = cleaned.rfind('.')
        if last_dot > last_comma:
            # dot is decimal, comma is thousands
