import pandas as pd
import numpy as np

df = pd.read_csv('/app/dataset/data.csv')
df['file_idx'] = np.arange(len(df))

def run_test(filter_channel_before, filter_date_before):
    # parse amount (enclosed mode)
    def parse_amount(val):
        if pd.isna(val): return np.nan
        s = str(val).strip()
        if not s: return np.nan
        is_neg = ('CR' in s) or ('-' in s) or (s.startswith('(') and s.endswith(')'))
        s_clean = s.replace('C1', '').replace('C2', '')
        cleaned = ''.join(c for c in s_clean if c.isdigit() or c in ',.')
        if not cleaned: return np.nan
        if ',' in cleaned and '.' in cleaned:
            if cleaned.rfind('.') > cleaned.rfind(','):
                num_str = cleaned.replace(',', '')
            else:
                num_str = cleaned.replace('.', '').replace(',', '.')
        elif ',' in cleaned:
            if len(cleaned) - 1 - cleaned.rfind(',') == 2:
                num_str = cleaned.replace(',', '.')
            else:
                num_str = cleaned.replace(',', '')
        elif '.' in cleaned:
            if len(cleaned) - 1 - cleaned.rfind('.') == 2:
                num_str = cleaned
            else:
                num_str = cleaned.replace('.', '')
        else:
            num_str = cleaned
        v = float(num_str)
        return -v if is_neg else v

    # parse notes
    def parse_notes(val):
        if pd.isna(val): return None, 0.0, 0.0, False
        s = str(val).strip()
        items, adj_pct, fee, waive = None, 0.0, 0.0, False
        for part in s.split(';'):
            part = part.strip()
            if not part: continue
            if '=' in part:
                k, v = part.split('=', 1)
                k, v = k.strip().lower(), v.strip()
                if k == 'items':
                    try: items = int(v)
                    except: pass
                elif k == 'adj':
                    try: adj_pct = float(v.rstrip('%').strip()) / 100.0
                    except: pass
                elif k == 'fee':
                    try: fee = float(v)
                    except: pass
                elif k == 'waive':
                    waive = (v.lower() == 'true')
        return items, adj_pct, fee, waive

    df_w = df.copy()
    df_w['base_amount'] = [parse_amount(x) for x in df_w['amount_str']]
    pn = [parse_notes(x) for x in df_w['notes']]
    df_w['items'] = [p[0] for p in pn]
    df_w['adj_pct'] = [p[1] for p in pn]
    df_w['fee'] = [p[2] for p in pn]
    df_w['waive'] = [p[3] for p in pn]

    nets = []
    for ba, ap, fee, w in zip(df_w['base_amount'], df_w['adj_pct'], df_w['fee'], df_w['waive']):
        if np.isnan(ba): nets.append(np.nan)
        elif w: nets.append(0.0)
        else: nets.append(ba * (1.0 + ap) + fee)
    df_w['net'] = nets

    # Optional pre-filtering
    if filter_date_before:
        df_w = df_w[df_w['event_time'].notna() & df_w['event_time'].between('2025-10-01 00:00:00', '2025-12-31 23:59:59')]
    if filter_channel_before:
        df_w = df_w[~df_w['channel'].astype(str).str.strip().str.lower().eq('phone')]

    df_w['has_et'] = df_w['event_time'].notna().astype(int)
    df_w['et_sort'] = df_w['event_time'].fillna('')
    df_w['has_real_net'] = (df_w['net'].notna() & np.isfinite(df_w['net'])).astype(int)

    df_sorted = df_w.sort_values(
        by=['has_et', 'et_sort', 'has_real_net', 'file_idx'],
        ascending=[False, False, False, True]
    )
    df_dedup = df_sorted.drop_duplicates(subset=['record_id'], keep='first').copy()

    # Post-filtering
    cond = (
        df_dedup['event_time'].notna() &
        (df_dedup['event_time'] >= '2025-10-01 00:00:00') &
        (df_dedup['event_time'] <= '2025-12-31 23:59:59') &
        (~df_dedup['channel'].astype(str).str.strip().str.lower().eq('phone')) &
        df_dedup['net'].notna() &
        np.isfinite(df_dedup['net'])
    )
    df_final = df_dedup[cond].copy()

    df_final['month'] = df_final['event_time'].str[:7]
    def calc_group(g):
        med = g['net'].median()
        mad = (g['net'] - med).abs().median()
        if mad == 0: z = np.zeros(len(g))
        else: z = 0.6745 * (g['net'] - med) / mad
        return pd.Series(z, index=g.index)

    df_final['robust_z'] = df_final.groupby(['region', 'month'], group_keys=False).apply(calc_group)
    items_eff = [1.0 if (it is None or pd.isna(it)) else max(1.0, float(it)) for it in df_final['items']]
    df_final['anomaly_score'] = df_final['robust_z'].abs() * np.log1p(items_eff)
    df_final['abs_robust_z'] = df_final['robust_z'].abs()

    ranked = df_final.sort_values(
        by=['anomaly_score', 'abs_robust_z', 'event_time', 'record_id'],
        ascending=[False, False, False, True],
        kind='mergesort'
    )
    return len(df_final), ranked['record_id'].head(10).tolist()

for f_ch in [False, True]:
    for f_dt in [False, True]:
        cnt, top10 = run_test(f_ch, f_dt)
        print(f'filter_ch_before={str(f_ch):5} filter_dt_before={str(f_dt):5} | count={cnt:3} | top10={top10}')
"

